namespace IceScreenTouch.Core;

/// <summary>
/// Lets only paired devices count as input clients (security review, 2026-11-07). The GATT layer asks for encryption on
/// the input reports, but the subscription descriptor is generated by Windows, so an unpaired central that manages to
/// subscribe would otherwise receive the touch and keyboard reports. The gate checks every new subscriber in the
/// background (never on the notify path): a device that is not known to be paired (still being checked, or the lookup
/// failed) is not <see cref="IsPaired"/>. A subscriber that is not confirmed yet is checked again and again, with
/// growing pauses, until it is confirmed or unsubscribes: Windows may report a new pairing late, and an iPhone that is
/// bonded does not subscribe again just because we ignored it.
/// </summary>
public sealed class PairedSubscriberGate : IDisposable
{
    // Pauses between the lookups of one unconfirmed device: 1.5 s, 3 s, 5 s, 10 s, then every 20 s.
    private static readonly TimeSpan[] Backoff = [TimeSpan.FromSeconds(1.5), TimeSpan.FromSeconds(3), TimeSpan.FromSeconds(5), TimeSpan.FromSeconds(10)];
    private static readonly TimeSpan SteadyInterval = TimeSpan.FromSeconds(20);

    // At the steady interval, an unconfirmed device is mentioned in the log at most this often.
    private static readonly TimeSpan ReminderInterval = TimeSpan.FromMinutes(1);

    // Update() asks an unconfirmed device for an extra lookup, but not when the last one was this recent.
    private static readonly TimeSpan MinRecheck = TimeSpan.FromSeconds(1);

    private readonly Func<string, CancellationToken, Task<bool?>> _lookup;
    private readonly Action<string> _log;
    private readonly TimeProvider _time;
    private readonly CancellationTokenSource _cts = new();
    private readonly Lock _lock = new();
    private readonly Dictionary<string, Entry> _entries = new(StringComparer.Ordinal);
    private bool _disposed;

    /// <summary>Creates a gate.</summary>
    /// <param name="lookup">Whether a device is paired (true / false), or null when that could not be found out. May throw.</param>
    /// <param name="log">Receives log lines (device IDs go through <see cref="LogPrivacy.LogId"/>).</param>
    /// <param name="time">The clock for the pauses between lookups (tests pass a fake one).</param>
    public PairedSubscriberGate(Func<string, CancellationToken, Task<bool?>> lookup, Action<string>? log = null, TimeProvider? time = null)
    {
        ArgumentNullException.ThrowIfNull(lookup);
        _lookup = lookup;
        _log = log ?? (_ => { });
        _time = time ?? TimeProvider.System;
    }

    /// <summary>Raised (on a thread-pool thread) when a device has been found to be paired.</summary>
    public event EventHandler? PairedDeviceAdded;

    /// <summary>True when the device is subscribed and was found to be paired. Cheap; safe on the notify path.</summary>
    public bool IsPaired(string deviceId)
    {
        lock (_lock)
        {
            return _entries.TryGetValue(deviceId, out var entry) && entry.Paired;
        }
    }

    /// <summary>The devices of <paramref name="deviceIds"/> that are known to be paired.</summary>
    public List<string> Filter(IEnumerable<string> deviceIds)
    {
        lock (_lock)
        {
            return [.. deviceIds.Where(id => _entries.TryGetValue(id, out var entry) && entry.Paired)];
        }
    }

    /// <summary>
    /// Tells the gate which devices are subscribed now (the complete list: the last call wins). A device that is new gets
    /// checked in the background; one that is gone is forgotten, so it is checked again when it subscribes again; one
    /// that is not confirmed yet gets an extra lookup right away.
    /// </summary>
    public void Update(IReadOnlyCollection<string> subscribedIds)
    {
        ArgumentNullException.ThrowIfNull(subscribedIds);
        List<Entry> started = [];
        List<CancellationTokenSource> cancel = [];
        lock (_lock)
        {
            if (_disposed)
            {
                return;
            }

            foreach (var gone in _entries.Keys.Where(id => !subscribedIds.Contains(id)).ToList())
            {
                cancel.Add(_entries[gone].Cts);
                _entries.Remove(gone);
            }

            foreach (var id in subscribedIds)
            {
                if (!_entries.TryGetValue(id, out var entry))
                {
                    entry = new Entry(id, CancellationTokenSource.CreateLinkedTokenSource(_cts.Token), _time.GetTimestamp());
                    _entries[id] = entry;
                    started.Add(entry);
                }
                else if (!entry.Paired && entry.Wake is { } wake && _time.GetElapsedTime(entry.LastAttempt) >= MinRecheck)
                {
                    cancel.Add(wake);
                }
            }
        }

        // Outside the lock: cancelling runs the continuations of the waiting checks.
        foreach (var source in cancel)
        {
            SafeCancel(source);
        }

        foreach (var entry in started)
        {
            _ = CheckAsync(entry);
        }
    }

    /// <summary>Stops the checks in progress.</summary>
    public void Dispose()
    {
        lock (_lock)
        {
            if (_disposed)
            {
                return;
            }

            _disposed = true;
            _entries.Clear();
        }

        // Not disposed: checks that are still running read the token. They stop on this.
        SafeCancel(_cts);
    }

    // Never faults: it is started without anyone awaiting it.
    private async Task CheckAsync(Entry entry)
    {
        var ct = entry.Cts.Token;
        try
        {
            var round = 0;
            while (!ct.IsCancellationRequested)
            {
                lock (_lock)
                {
                    entry.LastAttempt = _time.GetTimestamp();
                }

                bool? paired = null;
                string? failure = null;
                try
                {
                    paired = await _lookup(entry.Id, ct).ConfigureAwait(false);
                }
                catch (OperationCanceledException) when (ct.IsCancellationRequested)
                {
                    return;
                }
                catch (Exception ex)
                {
                    failure = ex.Message;
                }

                if (paired == true)
                {
                    Accept(entry);
                    return;
                }

                if (!entry.Reported)
                {
                    entry.Reported = true;
                    entry.LastReminder = _time.GetTimestamp();
                    Log($"{LogPrivacy.LogId(entry.Id)} subscribed to the input reports but is {Describe(paired, failure)}; ignoring it for now (it gets no input) and checking again");
                }
                else if (round >= Backoff.Length && _time.GetElapsedTime(entry.LastReminder) >= ReminderInterval)
                {
                    // On the 20 s interval: now and then, so that a real phone that stays excluded shows in the log.
                    entry.LastReminder = _time.GetTimestamp();
                    Log($"{LogPrivacy.LogId(entry.Id)} is still not confirmed paired after {_time.GetElapsedTime(entry.Subscribed).TotalSeconds:0} s; still ignoring it");
                }

                await WaitAsync(entry, round++, ct).ConfigureAwait(false);
            }
        }
        catch (OperationCanceledException)
        {
            // Unsubscribed or disposed.
        }
        catch (Exception ex)
        {
            Log($"{LogPrivacy.LogId(entry.Id)}: pairing check stopped ({ex.Message}); it is started again by the next update");
            lock (_lock)
            {
                // Forgotten, so that the next Update() starts a fresh check instead of leaving the device ignored.
                if (_entries.TryGetValue(entry.Id, out var current) && current == entry)
                {
                    _entries.Remove(entry.Id);
                }
            }
        }
        finally
        {
            entry.Cts.Dispose();
        }
    }

    private static string Describe(bool? paired, string? failure) =>
        paired == false ? "not paired" : $"not known to be paired (lookup failed{(failure is null ? string.Empty : ": " + failure)})";

    // Waits for the next lookup; Update() may end the wait early.
    private async Task WaitAsync(Entry entry, int round, CancellationToken ct)
    {
        using var wake = CancellationTokenSource.CreateLinkedTokenSource(ct);
        lock (_lock)
        {
            entry.Wake = wake;
        }

        try
        {
            await Task.Delay(round < Backoff.Length ? Backoff[round] : SteadyInterval, _time, wake.Token).ConfigureAwait(false);
        }
        catch (OperationCanceledException) when (!ct.IsCancellationRequested)
        {
            // Woken for an extra lookup.
        }
        finally
        {
            lock (_lock)
            {
                entry.Wake = null;
            }
        }
    }

    private void Accept(Entry entry)
    {
        lock (_lock)
        {
            if (!_entries.TryGetValue(entry.Id, out var current) || current != entry)
            {
                return;
            }

            entry.Paired = true;
        }

        var took = _time.GetElapsedTime(entry.Subscribed);
        Log($"{LogPrivacy.LogId(entry.Id)} is paired (confirmed {took.TotalSeconds:0.0} s after it subscribed{(entry.Reported ? ", after being ignored" : string.Empty)}); its subscription is accepted");
        try
        {
            PairedDeviceAdded?.Invoke(this, EventArgs.Empty);
        }
        catch (Exception ex)
        {
            Log($"{LogPrivacy.LogId(entry.Id)}: a handler of the pairing event failed ({ex.Message})");
        }
    }

    private void Log(string line)
    {
        try
        {
            _log(line);
        }
        catch (Exception)
        {
            // A failing logger must not end a check.
        }
    }

    private static void SafeCancel(CancellationTokenSource source)
    {
        try
        {
            source.Cancel();
        }
        catch (ObjectDisposedException)
        {
            // The check ended and released it already.
        }
    }

    private sealed class Entry(string id, CancellationTokenSource cts, long subscribed)
    {
        public string Id { get; } = id;

        /// <summary>Cancelled when the device unsubscribes or the gate is disposed; owned by its check.</summary>
        public CancellationTokenSource Cts { get; } = cts;

        public long Subscribed { get; } = subscribed;

        // The next four are guarded by the gate's lock (Reported only by the check).
        public bool Paired { get; set; }

        public long LastAttempt { get; set; } = subscribed;

        public CancellationTokenSource? Wake { get; set; }

        public bool Reported { get; set; }

        public long LastReminder { get; set; }
    }
}
